//const uint32_t UTF8[];
//const uint16_t *Hangul[] =  
//ªÁøÎπ˝
//char hbuf[20];
//char   buf[0] = 0xEA ~ buf[8]=0xb0 buf[0];
//UTF8_EUC_KR_Conv(buf, hbuf);

uint16_t UTF8_EUC_KR_Conv(uint32_t utf8)
{
    int i, size;
    uint16_t code;
    char    buf[12];
    
    size = sizeof(UTF8) / sizeof(uint32_t);
    for(i=0; i <size; i++)
    {
        if(UTF8[i]==utf8)
        {
            strcpy(buf, (char *)Hangul[i]);
            code = buf[0] << 8 | buf[1];
            return(code);
        }
    }
    return(0);    
}

int Conv(char *buf, char *hbuf)
{
    char    hi, mid, low;
    int  i;
    uint32_t code;
    uint16_t result;
    int size = strlen(buf);
    
    //Dprintf("size = %d\n", sizeof(buf));
    
    for(i=0; i<size; i+=3)
    {
        hi = buf[i]; mid=buf[i+1]; low=buf[i+2];
        code = hi << 16 | mid << 8 | low;
        //Dprintf("code = %08x\n", code);
        
        result = UTF8_EUC_KR_Conv(code);
        if(result==0) 
        {
            //Dprintf("UTF8 Code Error\n");
            return(0);
        }
        //Dprintf("Result=%08x\n", result);
        *hbuf++ = (char)((result >> 8) & 0x00ff);
        *hbuf++ = (char)(result  & 0x00ff);
    }
    *hbuf = 0;
    return(1);
}

int Conv_EK(char *sbuf, char *dbuf)
{
    char    hi, mid, low;
//    int  i;
    uint32_t code;
    uint16_t result;
    int size = strlen(sbuf);
    
    //Dprintf("size = %d\n", sizeof(sbuf));
    while(*sbuf)
	{
		//øµπÆ¿Ã∏È ±◊¥Î∑Œ¿˙¿Â«—¥Ÿ.
		if(*sbuf >=0x20 && *sbuf < 0x80)
		{
			*dbuf++ = *sbuf++;
		}
		else //UTF-8 «—±€¿Ã∏È 3πŸ¿Ã∆Æ∏¶ ¿–æÓº≠ øœº∫«—±€∑Œ ∫Ø»Ø«—¥Ÿ.
		{
			hi = *sbuf++; mid=*sbuf++; low=*sbuf++;
			code = hi << 16 | mid << 8 | low;
			//Dprintf("code = %08x\n", code);
				
			result = UTF8_EUC_KR_Conv(code);
			if(result==0) 
			{
				//Dprintf("UTF8 Code Error\n");
				return(0);
			}
			//Dprintf("Result=%08x\n", result);
			*dbuf++ = (char)((result >> 8) & 0x00ff);
			*dbuf++ = (char)(result  & 0x00ff);
		}
	}
    *dbuf = 0;
    return(1);
}

void UTF8_Test(void)
{
    char    hbuf[32];
    char    buf[] = {0xED, 0x99, 0x8D, 0xEA, 0xB8, 0xB8, 0xEB, 0x8F, 0x99, 0x00 };
    Conv(buf, hbuf);
    Dprintf("Out=%s\n", hbuf );
}

